web/assets/app.css.old:
@media (max-width: 600px) {
  table.stack, table.stack thead, table.stack tbody, table.stack tr, table.stack th, table.stack td { display: block; }
  table.stack thead { position: absolute; left: -9999px; }
  table.stack tr { border-top: 1px solid var(--line); padding: .4rem 0; }
  table.stack td { border: 0; padding: .2rem .8rem; }
  table.stack td::before { content: attr(data-label); display: block; font-family: var(--font-mono); font-size: .75rem; letter-spacing: .08em; text-transform: uppercase; color: var(--muted); }
  table.stack td.num { text-align: left; white-space: normal; }
  table.stack td::before { white-space: normal; }
  table.stack td { overflow-wrap: anywhere; }
  table.stack tfoot td:empty { display: none; }
}

web/assets/app.css.new:
.table-wrap:focus-visible { outline: 2px solid var(--teal-2); }
.binding pre { max-width: 100%; overflow: auto; }
.fold summary { overflow-wrap: anywhere; }

web/assets/app.js.new:
function fitCheck() {
  var over = wrap.scrollWidth > wrap.clientWidth + 1, tall = wrap.scrollHeight > wrap.clientHeight + 1;
  hint.hidden = !over && !tall;
  hint.textContent = (over ? 'Scroll sideways to see all ' + opts.header.length + ' columns. ' : '') + (tall ? 'Scroll inside this table; headers stay in view.' : '');
  wrap.classList.toggle('is-scrollable', over);
}

web/assets/case-study.css.new:
.case-result-wrap { max-height: min(65vh, 34rem); }
.case-points { padding-left: 1.25rem; margin: .8rem 0 1.2rem; color: var(--ink-soft); }
.case-points li { padding: .3rem 0 .3rem .15rem; }

